import{_ as n,o as a,c as i,a2 as t}from"./chunks/framework.1lnE8eph.js";const h=JSON.parse('{"title":"Open DS Component API and Foundations Update","description":"","frontmatter":{},"headers":[],"relativePath":"specs/004-open-ds-update.md","filePath":"specs/004-open-ds-update.md"}'),o={name:"specs/004-open-ds-update.md"};function s(r,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="open-ds-component-api-and-foundations-update" tabindex="-1">Open DS Component API and Foundations Update <a class="header-anchor" href="#open-ds-component-api-and-foundations-update" aria-label="Permalink to &quot;Open DS Component API and Foundations Update&quot;">​</a></h1><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to &quot;1. Scope&quot;">​</a></h2><p>Compare the existing Bus Map design system and its previous Open DS baseline with the latest supplied Open DS version. Identify and fill verified gaps in the components, foundations, documentation and validation used by Bus Map.</p><p>Delivered in <a href="https://github.com/airafa/bus-map/pull/4" target="_blank" rel="noreferrer">PR #4</a>.</p><ul><li>Previous reference: <a href="https://github.com/3dyonic/Open-DS/commit/3c8ff13" target="_blank" rel="noreferrer">3c8ff13</a>.</li><li>Updated reference: Open DS 0.2.1 at <a href="https://github.com/3dyonic/Open-DS/commit/30d187b4c833b5348e8c13ad7809a8b16860d404" target="_blank" rel="noreferrer">30d187b</a>.</li><li>Include the applicable OD-234, OD-235, OD-239, OD-240 and OD-242 updates.</li><li>Preserve the CSS Modules adaptation, Floating UI controls and Lego dialog integration.</li><li>Do not add unused upstream catalog components, replace the UI framework or introduce unnecessary application dependencies.</li></ul><h2 id="_2-component-token-apis" tabindex="-1">2. Component token APIs <a class="header-anchor" href="#_2-component-token-apis" aria-label="Permalink to &quot;2. Component token APIs&quot;">​</a></h2><ul><li>Synchronize the updated Dense data semantic and component tokens, retaining aliases.</li><li>Include all 1,299 upstream token keys rather than the previous 195-key subset.</li><li>Wire buttons, selects, menus, dialogs, panels and tables to their corresponding component token APIs.</li><li>Apply the scheme&#39;s typography, weights, control dimensions, borders and spacing through those APIs.</li><li>Keep shared overlay tokens for portaled surfaces where appropriate.</li><li>Preserve product overrides separately from generated upstream tokens.</li></ul><h2 id="_3-spacing-and-dialog-presentation" tabindex="-1">3. Spacing and dialog presentation <a class="header-anchor" href="#_3-spacing-and-dialog-presentation" aria-label="Permalink to &quot;3. Spacing and dialog presentation&quot;">​</a></h2><ul><li>Generate and document the component spacing map.</li><li>Use named layout roles between groups and named component steps inside components.</li><li>Keep Dense data spacing on its 4px grid, with steps up to 48px and the fixed 2px optical hairline.</li><li>Do not treat runtime table geometry, viewport dimensions or icon sizes as spacing.</li><li>Use the dialog container inset for header and content padding: 16px in Dense data.</li><li>Use the heading role for dialog titles and the body role for descriptions.</li><li>Preserve dragging, modal focus containment, focus restoration and nested select portals.</li></ul><h2 id="_4-theme-states-and-responsiveness" tabindex="-1">4. Theme states and responsiveness <a class="header-anchor" href="#_4-theme-states-and-responsiveness" aria-label="Permalink to &quot;4. Theme states and responsiveness&quot;">​</a></h2><ul><li>Give menu items body-sized labels and visible dedicated hover feedback.</li><li>Keep select-option hover distinct from the selected fill in every product theme.</li><li>Require input and secondary-action control borders to meet the Open DS strong-border contrast threshold of 3:1.</li><li>Preserve quiet decorative panel and table borders.</li><li>Target Floating UI triggers, not obsolete native-select selectors, in responsive header and documentation styles.</li><li>Preserve all six product themes, monochrome-first ordering, the system-matched default and theme branding.</li><li>Preserve 36px table rows, table/Gantt selection backgrounds and 2px outlines, virtualized rows, route identities and production editor restrictions.</li></ul><h2 id="_5-documentation-and-decision-reference" tabindex="-1">5. Documentation and decision reference <a class="header-anchor" href="#_5-documentation-and-decision-reference" aria-label="Permalink to &quot;5. Documentation and decision reference&quot;">​</a></h2><ul><li>Record verified gaps and their implemented resolutions in the design-system documentation.</li><li>Add the updated Open DS version and component spacing map to the interactive showcase.</li><li>Show each applied decision&#39;s answer, reason and preceding dependencies.</li><li>Show the downstream answers, usage rules and component variants each decision determines.</li><li>Generate decision consequences using the upstream reference engine rather than maintaining a separate interpretation.</li><li>Keep components before the theme gallery and preserve documentation scrolling.</li></ul><h2 id="_6-validation-and-delivery" tabindex="-1">6. Validation and delivery <a class="header-anchor" href="#_6-validation-and-delivery" aria-label="Permalink to &quot;6. Validation and delivery&quot;">​</a></h2><ul><li>Run the matching local Open DS MCP and require its version to match the synchronized source.</li><li>Preserve local reference-folder modifications; use a complete separate reference checkout when runtime or builder files are missing.</li><li>Verify 30 applied decisions, including reasons, dependencies and consequences.</li><li>Read the button, input, select, table, dialog, dropdown-menu, context-menu and card guides.</li><li>Verify generated component aliases and values in light and dark modes, all spacing steps, scale landings and consumed per-theme token chains.</li><li>Check all six product palettes against live contrast guidance and run <code>check_ui</code> on affected UI sources.</li><li>Run existing design-system regression tests, strict package TypeScript checking and a production Yarn build.</li><li>Validate dropdown hover/selection, menu hover, nested dialog dropdown dismissal and Escape ordering in the browser across all six themes.</li><li>Validate narrow-screen headers, documentation scrolling, row outlines, virtualization and dialog typography/padding.</li><li>Commit and push the update through a pull request against <code>main</code>; merge when requested.</li><li>Keep GitHub Pages publication separate unless explicitly requested.</li></ul>',15)])])}const m=n(o,[["render",s]]);export{h as __pageData,m as default};
